{"content":"const puppeteer = require('puppeteer');

const checks = {
  passed: [],
  failed: [],
};

function pass(msg) {
  checks.passed.push(msg);
  console.log(`PASS: ${msg}`);
}

function fail(msg, evidence) {
  checks.failed.push({ msg, evidence });
  console.log(`FAIL: ${msg}`);
  if (evidence) console.log(`  Evidence: ${JSON.stringify(evidence)}`);
}

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    executablePath: '/usr/bin/chromium-browser',
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();

  try {
    await page.goto('http://localhost:5173/', { waitUntil: 'networkidle2' });
    await page.waitForTimeout(1000);

    // Header title
    const headerTitle = await page.$eval('[data-component="Header"]', el => el.textContent).catch(() => null);
    if (headerTitle === 'Hello App') pass('Header title is "Hello App"');
    else fail('Header title should be "Hello App"', { headerTitle });

    // Footer text
    const footerText = await page.$eval('[data-component="Footer"]', el => el.textContent).catch(() => null);
    if (footerText && footerText.includes('Built with @codesweep-ai/ui')) pass('Footer text contains "Built with @codesweep-ai/ui"');
    else fail('Footer text should contain "Built with @codesweep-ai/ui"', { footerText });

    // Greeting text
    const greeting = await page.$eval('h1', el => el.textContent).catch(() => null);
    if (greeting === 'Hello, world!') pass('Greeting text is "Hello, world!"');
    else fail('Greeting text should be "Hello, world!"', { greeting });

    // Greeting style
    const greetingStyles = await page.$eval('h1', el => {
      const s = window.getComputedStyle(el);
      return {
        fontSize: s.fontSize,
        fontWeight: s.fontWeight,
        textAlign: s.textAlign,
        color: s.color,
      };
    }).catch(() => null);
    if (greetingStyles) {
      console.log('Greeting computed styles:', JSON.stringify(greetingStyles));
      if (parseFloat(greetingStyles.fontWeight) >= 700) pass('Greeting is bold');
      else fail('Greeting should be bold', { fontWeight: greetingStyles.fontWeight });
      if (greetingStyles.textAlign === 'center') pass('Greeting is centered');
      else fail('Greeting should be centered', { textAlign: greetingStyles.textAlign });
    } else {
      fail('Could not read greeting styles');
    }

    // Button labels
    const buttons = await page.$$eval('[data-component="Button"]', btns => btns.map(b => b.textContent.trim()));
    if (JSON.stringify(buttons) === JSON.stringify(['Blue', 'Green', 'Amber', 'Red'])) {
      pass('Buttons are Blue, Green, Amber, Red in order');
    } else {
      fail('Button labels should be Blue, Green, Amber, Red', { buttons });
    }

    // Active button initially should be Blue/primary
    const initialVariants = await page.$$eval('[data-component="Button"]', btns =>
      btns.map(b => b.getAttribute('data-variant'))
    );
    console.log('Initial button variants:', JSON.stringify(initialVariants));
    if (initialVariants[0] === 'primary' && initialVariants.slice(1).every(v => v === 'secondary')) {
      pass('Initial active button (Blue) is primary, others secondary');
    } else {
      fail('Initial Blue button should be primary and others secondary', { initialVariants });
    }

    // Click each button and check greeting color + active variant
    const expectedTokens = [
      { label: 'Blue', token: 'var(--color-info)', rgb: null },
      { label: 'Green', token: 'var(--color-success)', rgb: null },
      { label: 'Amber', token: 'var(--color-warning)', rgb: null },
      { label: 'Red', token: 'var(--color-error)', rgb: null },
    ];

    for (let i = 0; i < expectedTokens.length; i++) {
      const { label } = expectedTokens[i];
      await page.click(`button:has-text("${label}")`);
      await page.waitForTimeout(200);

      const color = await page.$eval('h1', el => window.getComputedStyle(el).color);
      expectedTokens[i].rgb = color;
      console.log(`${label} clicked -> greeting color: ${color}`);

      const variants = await page.$$eval('[data-component="Button"]', btns =>
        btns.map(b => b.getAttribute('data-variant'))
      );
      if (variants[i] === 'primary' && variants.filter((_, idx) => idx !== i).every(v => v === 'secondary')) {
        pass(`${label} button active variant is primary, others secondary`);
      } else {
        fail(`${label} button should be primary and others secondary`, { variants, clicked: label });
      }
    }

    // Verify colors changed across clicks (distinct values)
    const colors = expectedTokens.map(t => t.rgb);
    const uniqueColors = [...new Set(colors)];
    if (uniqueColors.length === 4) pass('All four colour clicks produce distinct greeting colours');
    else fail('Colour clicks should produce four distinct colours', { colors });

    // Check data-component attributes
    const requiredComponents = ['Header', 'Footer', 'Button', 'Card', 'Page', 'AppShell'];
    for (const name of requiredComponents) {
      const exists = await page.$(`[data-component="${name}"]`) !== null;
      if (exists) pass(`Rendered [data-component="${name}"]`);
      else fail(`Missing [data-component="${name}"]`);
    }

    // Layout: Card centered between Header and Footer
    const cardBox = await page.$eval('[data-component="Card"]', el => {
      const rect = el.getBoundingClientRect();
      return { top: rect.top, left: rect.left, width: rect.width, height: rect.height };
    }).catch(() => null);
    const pageBox = await page.$eval('[data-component="Page"]', el => {
      const rect = el.getBoundingClientRect();
      return { top: rect.top, left: rect.left, width: rect.width, height: rect.height };
    }).catch(() => null);
    if (cardBox && pageBox) {
      const cardCenterX = cardBox.left + cardBox.width / 2;
      const cardCenterY = cardBox.top + cardBox.height / 2;
      const pageCenterX = pageBox.left + pageBox.width / 2;
      const pageCenterY = pageBox.top + pageBox.height / 2;
      const xOff = Math.abs(cardCenterX - pageCenterX);
      const yOff = Math.abs(cardCenterY - pageCenterY);
      console.log(`Card center offset: x=${xOff}, y=${yOff}`);
      if (xOff <= 1 && yOff <= 1) pass('Card is centred in the page content area');
      else fail('Card should be centred in the page content area', { cardBox, pageBox, xOff, yOff });
    } else {
      fail('Could not measure Card/Page layout', { cardBox, pageBox });
    }

  } catch (e) {
    fail(`Script error: ${e.message}`);
    console.error(e);
  } finally {
    await browser.close();
  }

  console.log('\n=== SUMMARY ===');
  console.log(`Passed: ${checks.passed.length}`);
  console.log(`Failed: ${checks.failed.length}`);
  if (checks.failed.length > 0) {
    console.log('Failed checks:');
    checks.failed.forEach(f => console.log(` - ${f.msg}: ${JSON.stringify(f.evidence)}`));
    process.exit(1);
  }
})();
