      { label: 'Amber', token: 'var(--color-warning)', rgb: null },
      { label: 'Red', token: 'var(--color-error)', rgb: null },
    ];

    for (let i = 0; i < expectedTokens.length; i++) {
      const { label } = expectedTokens[i];
      const clicked = await page.evaluate((lbl) => {
        const btn = Array.from(document.querySelectorAll('[data-component="Button"]')).find(b => b.textContent.trim() === lbl);
        if (btn) { btn.click(); return true; }
        return false;
      }, label);
      if (!clicked) { fail(`Could not click ${label} button`); continue; }
      await delay(200);

      const color = await page.$eval('h1', el => window.getComputedStyle(el).color);
      expectedTokens[i].rgb = color;
      console.log(`${label} clicked -> greeting color: ${color}`);

      const variants = await page.$$eval('[data-component="Button"]', btns => btns.map(b => ({
        primary: b.classList.contains('cs-button--primary'),
        secondary: b.classList.contains('cs-button--secondary'),
      })));
