{"content":"const puppeteer = require('puppeteer');

const checks = { passed: [], failed: [] };
function pass(msg) { checks.passed.push(msg); console.log(`PASS: ${msg}`); }
function fail(msg, evidence) { checks.failed.push({ msg, evidence }); console.log(`FAIL: ${msg}`); if (evidence) console.log(`  Evidence: ${JSON.stringify(evidence)}`); }

const delay = ms => new Promise(r => setTimeout(r, ms));

function isTransparent(rgb) {
  return !rgb || rgb === 'rgba(0, 0, 0, 0)' || rgb === 'transparent';
}

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    executablePath: '/usr/bin/chromium-browser',
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });

  try {
    await page.goto('http://localhost:5173/', { waitUntil: 'networkidle2' });
    await delay(1000);

    const headerTitle = await page.$eval('[data-component="Header"]', el => el.textContent).catch(() => null);
    headerTitle === 'Hello App' ? pass('Header title is "Hello App"') : fail('Header title should be "Hello App"', { headerTitle });

    const footerText = await page.$eval('[data-component="Footer"]', el => el.textContent).catch(() => null);
    (footerText && footerText.trim() === 'Built with @codesweep-ai/ui') ? pass('Footer text is exactly "Built with @codesweep-ai/ui"') : fail('Footer text should be exactly "Built with @codesweep-ai/ui"', { footerText });

    const greeting = await page.$eval('h1', el => el.textContent).catch(() => null);
    greeting === 'Hello, world!' ? pass('Greeting text is "Hello, world!"') : fail('Greeting text should be "Hello, world!"', { greeting });

    const greetingStyles = await page.$eval('h1', el => {
      const s = window.getComputedStyle(el);
      return { fontSize: s.fontSize, fontWeight: s.fontWeight, textAlign: s.textAlign, color: s.color };
    }).catch(() => null);
    if (greetingStyles) {
      console.log('Greeting computed styles:', JSON.stringify(greetingStyles));
      parseFloat(greetingStyles.fontWeight) >= 700 ? pass('Greeting is bold (font-weight >= 700)') : fail('Greeting should be bold', { fontWeight: greetingStyles.fontWeight });
      greetingStyles.textAlign === 'center' ? pass('Greeting text is centered') : fail('Greeting text should be centered', { textAlign: greetingStyles.textAlign });
      greetingStyles.fontSize === '32px' ? pass('Greeting font size is 32px (2rem)') : fail('Greeting font size should be 32px (2rem)', { fontSize: greetingStyles.fontSize });
    } else {
      fail('Could not read greeting styles');
    }

    // Buttons initial state
    let buttons = await page.$$eval('[data-component="Button"]', btns => btns.map(b => ({
      text: b.textContent.trim(),
      bg: window.getComputedStyle(b).backgroundColor,
    })));
    console.log('Initial buttons:', JSON.stringify(buttons));
    const labels = buttons.map(b => b.text);
    JSON.stringify(labels) === JSON.stringify(['Blue', 'Green', 'Amber', 'Red']) ? pass('Buttons are Blue, Green, Amber, Red in order') : fail('Button labels should be Blue, Green, Amber, Red', { labels });

    function checkActive(label, buttons) {
      const activeIndex = buttons.findIndex(b => b.text === label);
      const activeBg = activeIndex >= 0 ? buttons[activeIndex].bg : null;
      const othersTransparent = buttons.filter((_, i) => i !== activeIndex).every(b => isTransparent(b.bg));
      if (activeIndex >= 0 && !isTransparent(activeBg) && othersTransparent) {
        pass(`${label} button is primary (active), others are secondary`);
      } else {
        fail(`${label} button should be primary and others secondary`, { activeIndex, activeBg, othersTransparent, buttons });
      }
    }

    checkActive('Blue', buttons);

    const expectedColors = {
      Blue: 'rgb(96, 165, 250)',
      Green: 'rgb(52, 211, 153)',
      Amber: 'rgb(245, 158, 11)',
      Red: 'rgb(248, 113, 113)',
    };

    for (const label of Object.keys(expectedColors)) {
      const clicked = await page.evaluate((lbl) => {
        const btn = Array.from(document.querySelectorAll('[data-component="Button"]')).find(b => b.textContent.trim() === lbl);
        if (btn) { btn.click(); return true; }
        return false;
      }, label);
      if (!clicked) { fail(`Could not click ${label} button`); continue; }
      await delay(200);

      const color = await page.$eval('h1', el => window.getComputedStyle(el).color);
      console.log(`${label} clicked -> greeting color: ${color}`);
      const expected = expectedColors[label];
      if (color === expected) {
        pass(`${label} click sets greeting to expected resolved colour (${expected})`);
      } else {
        fail(`${label} click should set greeting to ${expected}`, { color, expected });
      }

      buttons = await page.$$eval('[data-component="Button"]', btns => btns.map(b => ({
        text: b.textContent.trim(),
        bg: window.getComputedStyle(b).backgroundColor,
      })));
      checkActive(label, buttons);
    }

    // data-component attributes
    for (const name of ['Header', 'Footer', 'Button', 'Card', 'Page', 'AppShell']) {
      const exists = await page.$(`[data-component="${name}"]`) !== null;
      exists ? pass(`Rendered [data-component="${name}"]`) : fail(`Missing [data-component="${name}"]`);
    }

    // Layout measurements
    const layout = await page.evaluate(() => {
      const h = document.querySelector('[data-component="Header"]')?.getBoundingClientRect();
      const f = document.querySelector('[data-component="Footer"]')?.getBoundingClientRect();
      const c = document.querySelector('[data-component="Card"]')?.getBoundingClientRect();
      const p = document.querySelector('[data-component="Page"]')?.getBoundingClientRect();
      const viewport = { width: window.innerWidth, height: window.innerHeight };
      return { header: h, footer: f, card: c, page: p, viewport };
    });
    console.log('Layout:', JSON.stringify(layout, null, 2));

    if (layout.page && layout.card) {
      const pageCX = layout.page.left + layout.page.width / 2;
      const pageCY = layout.page.top + layout.page.height / 2;
      const cardCX = layout.card.left + layout.card.width / 2;
      const cardCY = layout.card.top + layout.card.height / 2;
      const xOff = Math.abs(cardCX - pageCX);
      const yOff = Math.abs(cardCY - pageCY);
      (xOff <= 1 && yOff <= 1) ? pass('Card is centred within Page') : fail('Card should be centred within Page', { xOff, yOff, page: layout.page, card: layout.card });
    }

    if (layout.header && layout.footer && layout.card) {
      const contentTop = layout.header.bottom;
      const contentBottom = layout.footer.top;
      const contentHeight = contentBottom - contentTop;
      const contentMidY = contentTop + contentHeight / 2;
      const cardMidY = layout.card.top + layout.card.height / 2;
      const yOff = Math.abs(cardMidY - contentMidY);
      (yOff <= 1) ? pass('Card is centred vertically between Header and Footer') : fail('Card should be centred vertically between Header and Footer', { yOff, contentTop, contentBottom, cardMidY, contentMidY });
    }

    if (layout.page && layout.header && layout.footer) {
      const contentTop = layout.header.bottom;
      const contentBottom = layout.footer.top;
      const expectedHeight = contentBottom - contentTop;
      const actualHeight = layout.page.height;
      const heightDiff = Math.abs(actualHeight - expectedHeight);
      (heightDiff <= 1) ? pass('Page fills available viewport height between Header and Footer') : fail('Page should fill available viewport height between Header and Footer', { expectedHeight, actualHeight, heightDiff });
    }

    // Verify greeting color is driven by CSS variable (not hard-coded hex) by checking inline style
    const h1Style = await page.$eval('h1', el => el.getAttribute('style')).catch(() => null);
    if (h1Style && h1Style.includes('var(--color-')) {
      pass('Greeting colour is set via CSS variable inline style');
    } else {
      fail('Greeting colour should be set via a CSS variable like var(--color-*)', { h1Style });
    }

  } catch (e) {
    fail(`Script error: ${e.message}`);
    console.error(e);
  } finally {
    await browser.close();
  }

  console.log('\n=== SUMMARY ===');
  console.log(`Passed: ${checks.passed.length}`);
  console.log(`Failed: ${checks.failed.length}`);
  if (checks.failed.length > 0) {
    console.log('Failed checks:');
    checks.failed.forEach(f => console.log(` - ${f.msg}: ${JSON.stringify(f.evidence)}`));
    process.exit(1);
  }
})();
