(async () => {
  const browser = await puppeteer.launch({ headless: true, executablePath: '/usr/bin/chromium-browser', args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  await page.goto('http://localhost:5173/', { waitUntil: 'networkidle2' });
  await new Promise(r => setTimeout(r, 1000));
  const styles = await page.evaluate(() => {
    const p = document.querySelector('[data-component=\"Page\"]');
    const c = document.querySelector('[data-component=\"Card\"]');
    const s = p ? window.getComputedStyle(p) : null;
    const cs = c ? window.getComputedStyle(c) : null;
    return {
      page: p ? { paddingLeft: s.paddingLeft, paddingRight: s.paddingRight, marginLeft: s.marginLeft, marginRight: s.marginRight, justifyContent: s.justifyContent, alignItems: s.alignItems, display: s.display, width: s.width, boxSizing: s.boxSizing } : null,
      card: c ? { marginLeft: cs.marginLeft, marginRight: cs.marginRight, boxSizing: cs.boxSizing, width: cs.width } : null,
    };
  });
  console.log(JSON.stringify(styles, null, 2));
  await browser.close();
})();
