const puppeteer = require('puppeteer');
(async () => {
  const browser = await puppeteer.launch({ headless: true, executablePath: '/usr/bin/chromium-browser', args: ['--no-sandbox', '--disable-setuid-sandbox'] });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  await page.goto('http://localhost:5173/', { waitUntil: 'networkidle2' });
  await new Promise(r => setTimeout(r, 1000));
  const s = await page.evaluate(() => {
    const b = document.body;
    const h = document.documentElement;
    const bs = window.getComputedStyle(b);
    const hs = window.getComputedStyle(h);
    return {
      body: { marginLeft: bs.marginLeft, paddingLeft: bs.paddingLeft },
      html: { marginLeft: hs.marginLeft, paddingLeft: hs.paddingLeft },
      viewport: window.innerWidth,
    };
  });
  console.log(JSON.stringify(s, null, 2));
  await browser.close();
})();
